/**
 ******************************************************************************
 * @file    fx_store.c
 * TEAM CODE (owner: Jack - audio input and SD storage) - written by the BJT2 team, not generated by STM32CubeMX.
 * Authors: written by Brendon (integrator) on 29-30 Oct 2026 for Jack's storage subsystem (best-ui), with an AI coding assistant.
 * @brief   Effect-file paths, the names DELETE accepts, the source hash and
 *          the effect-file header with its tag (see fx_store.h).
 *
 * Pure logic: no RTOS, no HAL, no FatFs (tests: Tests/test_fx_store.c).
 * Paths are built with snprintf into the caller's buffer and are checked to
 * fit: a path that does not fit is refused, never cut short. Numbers in the
 * header are little-endian, as in every WAV file.
 ******************************************************************************/
#include "fx_store.h"
#include <stdio.h>
#include <string.h>
#include <ctype.h>

/* The folder of each effect, indexed by its number (0 = no effect). The
 * names are short 8.3 folder names, and their order is UiEffect_t's. */
static const char *const s_folders[FXS_EFFECT_COUNT + 1U] = {
    NULL,           /* FXS_EFFECT_NONE: the original, no folder */
    "AUTOTUNE",     /* FXS_EFFECT_AUTOTUNE */
    "PITCHUP",      /* FXS_EFFECT_PITCHUP */
    "PITCHDN",      /* FXS_EFFECT_PITCHDN */
    "ROBOT",        /* FXS_EFFECT_ROBOT */
    "ECHO",         /* FXS_EFFECT_ECHO */
    "REVERB"        /* FXS_EFFECT_REVERB */
};

#define FXS_EXT_CHARS 4U            /* ".WAV" / ".TMP" */

/* The header's layout (fx_store.h): byte offsets and chunk sizes. */
#define FXS_RIFF_HEADER_BYTES 12U   /* "RIFF" <size> "WAVE" */
#define FXS_CHUNK_HEADER_BYTES 8U   /* a chunk id and its size */
#define FXS_FMT_BODY_BYTES    16U   /* PCM "fmt " body */
#define FXS_TAG_BODY_BYTES    16U   /* "bjfx" body: the fx_tag_t fields */
#define FXS_FMT_AT            12U   /* offset of the "fmt " chunk */
#define FXS_TAG_AT            36U   /* offset of the "bjfx" chunk */
#define FXS_DATA_AT           60U   /* offset of the "data" chunk */
#define FXS_PCM_FORMAT        1U    /* WAVE_FORMAT_PCM */
#define FXS_CHANNELS          1U    /* mono */
#define FXS_BITS              16U
#define FXS_BLOCK_ALIGN       2U    /* bytes per sample frame: 1 channel x 16 bit */
#define FXS_RATE_48K_HZ       48000U  /* a source at this rate needs no upsampler (src_48k = 1) */

/* FNV-1a 32-bit constants (the published offset basis and prime). */
#define FNV1A_OFFSET_BASIS    0x811C9DC5U
#define FNV1A_PRIME           0x01000193U

/* Length of name, looking at no more than max characters: a name field
 * may be full with no NUL in it. Returns max + 1 when there is no NUL in
 * the first max + 1 characters. */
static size_t bounded_length(const char *name, size_t max)
{
    size_t n = 0U;
    while (n <= max && name[n] != '\0')
    {
        n++;
    }
    return n;
}

/* True when text ends in ".WAV", in any case. */
static bool ends_in_wav(const char *text, size_t len)
{
    if (len < FXS_EXT_CHARS)
    {
        return false;
    }
    const char *ext = &text[len - FXS_EXT_CHARS];
    return (ext[0] == '.') &&
           (toupper((unsigned char)ext[1]) == 'W') &&
           (toupper((unsigned char)ext[2]) == 'A') &&
           (toupper((unsigned char)ext[3]) == 'V');
}

/* Check the path snprintf just wrote into out: false (and out = "") when
 * it did not fit. */
static bool path_fits(int written, char *out, size_t out_len)
{
    if (written < 0 || (size_t)written >= out_len)
    {
        out[0] = '\0';
        return false;
    }
    return true;
}

const char *fx_folder(uint8_t effect)
{
    if (effect < FXS_EFFECT_AUTOTUNE || effect > FXS_EFFECT_COUNT)
    {
        return NULL;
    }
    return s_folders[effect];
}

bool fx_name_ok(const char *name)
{
    if (name == NULL)
    {
        return false;
    }
    const size_t len = bounded_length(name, FXS_NAME_MAX_CHARS);
    if (len > FXS_NAME_MAX_CHARS || !ends_in_wav(name, len))
    {
        return false;
    }
    const size_t base_len = len - FXS_EXT_CHARS;
    if (base_len == 0U || base_len > FXS_BASE_MAX_CHARS || name[0] == '_')
    {
        return false;
    }
    for (size_t i = 0U; i < base_len; i++)
    {
        if (name[i] == '/' || name[i] == '\\' || name[i] == '.')
        {
            return false;
        }
    }
    return true;
}

bool fx_dir_path(uint8_t effect, char *out, size_t out_len)
{
    if (out == NULL || out_len == 0U)
    {
        return false;
    }
    const char *folder = fx_folder(effect);
    if (folder == NULL)
    {
        out[0] = '\0';
        return false;
    }
    return path_fits(snprintf(out, out_len, "%s/%s", FXS_ROOT_DIR, folder), out, out_len);
}

bool fx_file_path(uint8_t effect, const char *name, bool tmp, char *out, size_t out_len)
{
    if (out == NULL || out_len == 0U)
    {
        return false;
    }
    const char *folder = fx_folder(effect);
    if (folder == NULL || !fx_name_ok(name))
    {
        out[0] = '\0';
        return false;
    }
    if (!tmp)
    {
        return path_fits(snprintf(out, out_len, "%s/%s/%s", FXS_ROOT_DIR, folder, name), out, out_len);
    }
    /* The same name with ".TMP" in place of ".WAV" (fx_name_ok checked
     * that the part before ".WAV" has 1..8 characters). */
    char base[FXS_BASE_MAX_CHARS + 1U];
    const size_t base_len = strlen(name) - FXS_EXT_CHARS;
    memcpy(base, name, base_len);
    base[base_len] = '\0';
    return path_fits(snprintf(out, out_len, "%s/%s/%s.TMP", FXS_ROOT_DIR, folder, base), out, out_len);
}

bool fx_delete_path(uint8_t i, const char *name, char *out, size_t out_len)
{
    if (out == NULL || out_len == 0U)
    {
        return false;
    }
    out[0] = '\0';
    if (i >= FXS_DELETE_PATHS || !fx_name_ok(name))
    {
        return false;
    }
    if (i == 0U)
    {
        return path_fits(snprintf(out, out_len, "%s", name), out, out_len);
    }
    /* 1, 2 = folder 1's .WAV and .TMP; 3, 4 = folder 2's; ... */
    const uint8_t effect = (uint8_t)(((i - 1U) / 2U) + 1U);
    const bool tmp = (((i - 1U) % 2U) == 1U);
    return fx_file_path(effect, name, tmp, out, out_len);
}

/* ------------------------------------------------------------------------ */
/* Hash                                                                      */
/* ------------------------------------------------------------------------ */
uint32_t fx_hash_begin(void)
{
    return FNV1A_OFFSET_BASIS;
}

/* FNV-1a: for each byte, XOR it into the hash, then multiply by the prime.
 * Cheap, and any changed byte changes the result. */
uint32_t fx_hash_add(uint32_t hash, const uint8_t *data, size_t len)
{
    if (data == NULL)
    {
        return hash;
    }
    for (size_t i = 0U; i < len; i++)
    {
        hash ^= data[i];
        hash *= FNV1A_PRIME;
    }
    return hash;
}

/* ------------------------------------------------------------------------ */
/* Header and tag                                                            */
/* ------------------------------------------------------------------------ */
static void put_u16(uint8_t *at, uint16_t v)
{
    at[0] = (uint8_t)(v & 0xFFU);
    at[1] = (uint8_t)(v >> 8);
}

static void put_u32(uint8_t *at, uint32_t v)
{
    at[0] = (uint8_t)(v & 0xFFU);
    at[1] = (uint8_t)((v >> 8) & 0xFFU);
    at[2] = (uint8_t)((v >> 16) & 0xFFU);
    at[3] = (uint8_t)(v >> 24);
}

static uint16_t get_u16(const uint8_t *at)
{
    return (uint16_t)(at[0] | (at[1] << 8));
}

static uint32_t get_u32(const uint8_t *at)
{
    return (uint32_t)at[0] | ((uint32_t)at[1] << 8) | ((uint32_t)at[2] << 16) | ((uint32_t)at[3] << 24);
}

void fx_tag_from_src(fx_tag_t *tag, uint16_t version, uint8_t effect, const fx_src_t *src)
{
    if (tag == NULL || src == NULL)
    {
        return;
    }
    memset(tag, 0, sizeof(*tag));
    tag->src_size  = src->size;
    tag->src_hash  = src->hash;
    tag->version   = version;
    tag->effect    = effect;
    tag->src_48k   = (src->rate == FXS_RATE_48K_HZ) ? 1U : 0U;
    tag->src_fdate = src->fdate;
    tag->src_ftime = src->ftime;
}

storage_result_t fx_build_header(const fx_tag_t *tag, uint32_t data_bytes, uint8_t *out, size_t out_len)
{
    if (tag == NULL || out == NULL || out_len < FXS_HEADER_BYTES)
    {
        return STORAGE_INVALID_ARG;
    }
    memset(out, 0, FXS_HEADER_BYTES);

    /* "RIFF" <everything after these 8 bytes> "WAVE" */
    memcpy(&out[0], "RIFF", 4U);
    put_u32(&out[4], (FXS_HEADER_BYTES - FXS_CHUNK_HEADER_BYTES) + data_bytes);
    memcpy(&out[8], "WAVE", 4U);

    /* "fmt ": PCM, mono, 48 kHz, 16 bit */
    memcpy(&out[FXS_FMT_AT], "fmt ", 4U);
    put_u32(&out[FXS_FMT_AT + 4U], FXS_FMT_BODY_BYTES);
    put_u16(&out[FXS_FMT_AT + 8U], FXS_PCM_FORMAT);
    put_u16(&out[FXS_FMT_AT + 10U], FXS_CHANNELS);
    put_u32(&out[FXS_FMT_AT + 12U], FXS_RATE_HZ);
    put_u32(&out[FXS_FMT_AT + 16U], FXS_RATE_HZ * FXS_BLOCK_ALIGN);    /* bytes per second */
    put_u16(&out[FXS_FMT_AT + 20U], FXS_BLOCK_ALIGN);
    put_u16(&out[FXS_FMT_AT + 22U], FXS_BITS);

    /* "bjfx": what the file was made from */
    memcpy(&out[FXS_TAG_AT], "bjfx", 4U);
    put_u32(&out[FXS_TAG_AT + 4U], FXS_TAG_BODY_BYTES);
    put_u16(&out[FXS_TAG_AT + 8U], tag->version);
    out[FXS_TAG_AT + 10U] = tag->effect;
    out[FXS_TAG_AT + 11U] = tag->src_48k;
    put_u32(&out[FXS_TAG_AT + 12U], tag->src_size);
    put_u32(&out[FXS_TAG_AT + 16U], tag->src_hash);
    put_u16(&out[FXS_TAG_AT + 20U], tag->src_fdate);
    put_u16(&out[FXS_TAG_AT + 22U], tag->src_ftime);

    /* "data" <bytes>; the samples follow at byte 68 */
    memcpy(&out[FXS_DATA_AT], "data", 4U);
    put_u32(&out[FXS_DATA_AT + 4U], data_bytes);
    return STORAGE_OK;
}

/* Read the tag fields from the body of a "bjfx" chunk. */
static void read_tag_body(const uint8_t *body, fx_tag_t *tag)
{
    tag->version   = get_u16(&body[0]);
    tag->effect    = body[2];
    tag->src_48k   = body[3];
    tag->src_size  = get_u32(&body[4]);
    tag->src_hash  = get_u32(&body[8]);
    tag->src_fdate = get_u16(&body[12]);
    tag->src_ftime = get_u16(&body[14]);
}

/* Walk the chunks after "RIFF" <size> "WAVE" until "bjfx" (found), "data"
 * (no tag before the samples) or the end of buf. */
storage_result_t fx_parse_tag(const uint8_t *buf, size_t len, fx_tag_t *tag)
{
    if (buf == NULL || tag == NULL)
    {
        return STORAGE_INVALID_ARG;
    }
    if (len < FXS_RIFF_HEADER_BYTES || memcmp(&buf[0], "RIFF", 4U) != 0 || memcmp(&buf[8], "WAVE", 4U) != 0)
    {
        return STORAGE_CORRUPT;
    }
    size_t pos = FXS_RIFF_HEADER_BYTES;
    while ((len - pos) >= FXS_CHUNK_HEADER_BYTES)
    {
        const uint8_t *id = &buf[pos];
        const uint32_t size = get_u32(&buf[pos + 4U]);
        const size_t body = pos + FXS_CHUNK_HEADER_BYTES;
        if (memcmp(id, "data", 4U) == 0)
        {
            return STORAGE_NOT_FOUND;                  /* the samples start: there is no tag */
        }
        const size_t room = len - body;
        if (size > room)
        {
            return STORAGE_NOT_FOUND;                  /* the chunk runs past what was read */
        }
        if (memcmp(id, "bjfx", 4U) == 0 && size >= FXS_TAG_BODY_BYTES)
        {
            read_tag_body(&buf[body], tag);
            return STORAGE_OK;
        }
        pos = body + size + (size & 1U);               /* RIFF pads an odd-sized chunk to even */
        if (pos > len)
        {
            return STORAGE_NOT_FOUND;
        }
    }
    return STORAGE_NOT_FOUND;
}

bool fx_tag_matches(const fx_tag_t *found, const fx_tag_t *wanted)
{
    if (found == NULL || wanted == NULL)
    {
        return false;
    }
    return (found->version == wanted->version) &&
           (found->effect == wanted->effect) &&
           (found->src_48k == wanted->src_48k) &&
           (found->src_size == wanted->src_size) &&
           (found->src_hash == wanted->src_hash) &&
           (found->src_fdate == wanted->src_fdate) &&
           (found->src_ftime == wanted->src_ftime);
}
